'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has a `lastFieldOf` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasProp( p, 'lastFieldOf' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.lastFieldOf ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.lastFieldOf.call( value, 1 );
		};
	}
});

tape( 'the method throws an error if provided a second argument which is not an integer', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.lastFieldOf( 1, value );
		};
	}
});

tape( 'the method returns the field name of the last element strictly equal to a search element', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 1 ] );

	out = p.lastFieldOf( 1 );
	t.strictEqual( out, 'z', 'returns expected value' );

	out = p.lastFieldOf( 2 );
	t.strictEqual( out, 'y', 'returns expected value' );

	t.end();
});

tape( 'the method returns `undefined` if unable to locate a search element', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	out = p.lastFieldOf( 10 );
	t.strictEqual( out, void 0, 'returns expected value' );
	t.end();
});

tape( 'the method supports specifying a starting index', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 1 ] );

	out = p.lastFieldOf( 1, 1 );
	t.strictEqual( out, 'x', 'returns expected value' );
	t.end();
});

tape( 'the method supports specifying a negative starting index', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 1 ] );

	out = p.lastFieldOf( 1, -2 );
	t.strictEqual( out, 'x', 'returns expected value' );
	t.end();
});

tape( 'the method returns `undefined` if a negative starting index resolves to a negative index', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	out = p.lastFieldOf( 1, -10 );
	t.strictEqual( out, void 0, 'returns expected value' );
	t.end();
});

tape( 'the method clamps a starting index which exceeds the maximum tuple index', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	out = p.lastFieldOf( 3, 100 );
	t.strictEqual( out, 'z', 'returns expected value' );
	t.end();
});
